@startuml

class Employee {
  + name : string
  + department : string
  + staffNumber : int
}

class IdentityCard {
  + cardNumber : int
}

class GuestCard {
  + cardNumber : int
  + date : date
}

class CardReader {
  + verify(cardNumber : int) : boolean
}

class Barrier {
  + rise() : void
}

class CarPark {
  + isFull() : boolean
}

class Sign {
  + displayStatus(status : string) : void
}

class Car {}

Employee "1" -- "1" IdentityCard : wears
IdentityCard "1" -- "0..*" Car : belongs to
GuestCard "0..*" -- "0..*" Car : belongs to
CardReader "1" -- "1" IdentityCard : reads
CardReader "1" -- "1" Barrier : triggers
CarPark "1" -- "1" Sign : has
CarPark "1" -- "1" Barrier : has
Car "1" -- "1" Barrier : passes through
Car "1" -- "1" Barrier : passes through

@enduml

